import math

def _rendezvous_slot_intervals(sandbox):
    return sandbox.get_rendezvous_slots()

def build_agent(sandbox):
    return sandbox.get_seeker_body()

def agent_action(sandbox, agent_body, step_count):
    if not hasattr(agent_body, '_state'):
        agent_body._state = {'last_tx': 0.0, 'last_ty': 0.0, 'tvx': 0.0, 'tvy': 0.0}
    state = agent_body._state
    tx, ty = sandbox.get_target_position()
    sx, sy = sandbox.get_seeker_position()
    svx, svy = sandbox.get_seeker_velocity()

    # Estimate target velocity using a 5-step moving average
    if step_count % 5 == 0 and step_count > 5:
        dt = 5.0 / 60.0
        state['tvx'] = 0.5 * state['tvx'] + 0.5 * (tx - state['last_tx']) / dt
        state['tvy'] = 0.5 * state['tvy'] + 0.5 * (ty - state['last_ty']) / dt
        state['last_tx'], state['last_ty'] = tx, ty
    elif step_count <= 5:
        state['last_tx'], state['last_ty'] = tx, ty

    # Get corridor bounds
    x_lo, x_hi = sandbox.get_corridor_bounds()

    # Determine goal position
    if step_count < 110:
        # Activation phase: center of the corridor
        gx = (x_lo + x_hi) / 2
        gy = 1.55  # Match seeker's spawn y-coordinate
    else:
        # Use target position for rendezvous, or a mid-corridor fallback
        gx, gy = tx, ty  # During rendezvous slot
        # Non-slot fallback (can be improved)
        if not any(lo <= step_count <= hi for (lo, hi) in _rendezvous_slot_intervals(sandbox)):
            gx = 13.1 if (step_count // 120) % 2 == 0 else 13.5
            gy = 1.55

    # PD controller with updated gains
    if any(lo <= step_count <= hi for (lo, hi) in _rendezvous_slot_intervals(sandbox)):
        # In rendezvous slot: follow target with PD
        fx = 150.0 * (gx - sx) + 60.0 * (state['tvx'] - svx)
        fy = 150.0 * (gy - sy) + 60.0 * (state['tvy'] - svy)
    else:
        # Otherwise: stabilization in mid-corridor
        fx = 150.0 * (gx - sx) - 120.0 * svx
        fy = 180.0 * (gy - sy) - 45.0 * svy

    # Remove thrust clamping during activation
    if step_count >= 110 and abs(gx - sx) > 0.05:
        if abs(fx) < 110.0:
            fx = 110.0 if (gx - sx) > 0 else -110.0

    # Clamp to max thrust (200 N) if needed
    mag = math.sqrt(fx * fx + fy * fy)
    if mag > 200.0:
        fx, fy = fx * 200.0 / mag, fy * 200.0 / mag

    # Apply the computed force
    sandbox.apply_seeker_force(fx, fy)
